{"version":2,"items":[{"name":"SELECT SELECT catalog.event_seats SELECT catalog.event_seats catalog.events catalog.venues","span_id":"802e00aeef43f800","trace_id":"cbf99265793b4c6e8fa61d791b5484f6","parent_span_id":"859a4314e196cea0","start_timestamp":1792048845.1809418,"end_timestamp":1792048845.1909716,"is_segment":false,"status":"ok","attributes":{"sentry.origin":{"value":"auto.db.postgres","type":"string"},"sentry.op":{"value":"db","type":"string"},"db.system.name":{"value":"postgresql","type":"string"},"db.namespace":{"value":"r19a","type":"string"},"db.user":{"value":"tixly_app","type":"string"},"server.address":{"value":"localhost","type":"string"},"server.port":{"value":55632,"type":"integer"},"db.connection_string":{"value":"postgresql://localhost:55632/r19a","type":"string"},"db.query.text":{"value":"SELECT e.id, e.date_start::text AS \"dateStart\", e.status, e.term_note AS \"termNote\", e.cast_alternation AS \"castAlternation\", v.id AS \"venueId\", v.name AS \"venueName\", v.city, (SELECT count(*)::int FROM catalog.event_seats s WHERE s.event_id = e.id) AS capacity, (SELECT count(*)::int FROM catalog.event_seats s WHERE s.event_id = e.id AND s.status = ?) AS sold FROM catalog.events e LEFT JOIN catalog.venues v ON v.id = e.venue_id WHERE e.production_id = $1 AND e.promoter_id = $2 ORDER BY e.date_start","type":"string"},"db.query.summary":{"value":"SELECT SELECT catalog.event_seats SELECT catalog.event_seats catalog.events catalog.venues","type":"string"},"sentry.kind":{"value":"client","type":"string"},"sentry.trace_lifecycle":{"value":"stream","type":"string"},"sentry.segment.name":{"value":"GET /api/admin/productions/[id]","type":"string"},"sentry.segment.id":{"value":"ab276e010ded6cf1","type":"string"},"sentry.sdk.name":{"value":"sentry.javascript.nextjs","type":"string"},"sentry.sdk.version":{"value":"11.7.0","type":"string"},"sentry.release":{"value":"1b091be83b73ba11007ab287dfae68aa89487506","type":"string"},"sentry.environment":{"value":"producti